<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Personal Expense Tracker</title>
    <style>
        :root {
            --primary: #2563eb;
            --danger: #dc2626;
            --bg: #f8fafc;
            --card: #ffffff;
            --text: #1e293b;
        }

        body {
            font-family: system-ui, -apple-system, sans-serif;
            background-color: var(--bg);
            color: var(--text);
            margin: 0;
            padding: 20px;
            display: flex;
            justify-content: center;
        }

        .container {
            width: 100%;
            max-width: 600px;
            background: var(--card);
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
        }

        h1 { margin-top: 0; font-size: 1.5rem; }

        .form-group {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
            margin-bottom: 1rem;
        }

        .full-width { grid-column: span 2; }

        label { display: block; font-size: 0.875rem; margin-bottom: 4px; font-weight: 600; }

        input, select, textarea {
            width: 100%;
            padding: 8px;
            border: 1px solid #cbd5e1;
            border-radius: 4px;
            box-sizing: border-box;
        }

        button {
            cursor: pointer;
            background: var(--primary);
            color: white;
            border: none;
            padding: 10px 20px;
            border-radius: 4px;
            font-weight: bold;
        }

        #form-error {
            color: var(--danger);
            font-size: 0.875rem;
            margin-bottom: 1rem;
            min-height: 1.2rem;
        }

        .filters {
            background: #f1f5f9;
            padding: 1rem;
            border-radius: 4px;
            margin: 1.5rem 0;
        }

        .summary-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
            gap: 10px;
            margin-bottom: 1rem;
        }

        .cat-total {
            padding: 8px;
            background: #e2e8f0;
            border-radius: 4px;
            font-size: 0.875rem;
            text-align: center;
        }

        #total-display {
            font-size: 1.25rem;
            font-weight: bold;
            margin-bottom: 1rem;
            padding: 10px;
            border-left: 4px solid var(--primary);
        }

        .expense-list {
            list-style: none;
            padding: 0;
        }

        .expense {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 10px;
            border-bottom: 1px solid #e2e8f0;
        }

        .exp-info { display: flex; flex-direction: column; }
        .exp-date { font-size: 0.75rem; color: #64748b; }
        .exp-meta { font-weight: 600; }

        .exp-del {
            background: var(--danger);
            padding: 5px 10px;
            font-size: 0.75rem;
        }
    </style>
</head>
<body>

<div class="container">
    <h1>Expense Tracker</h1>

    <!-- Entry Form -->
    <form id="expense-form">
        <div class="form-group">
            <div>
                <label for="amount">Amount</label>
                <input type="number" id="amount" step="0.01" placeholder="0.00">
            </div>
            <div>
                <label for="category">Category</label>
                <select id="category">
                    <option value="groceries">Groceries</option>
                    <option value="transport">Transport</option>
                    <option value="bills">Bills</option>
                    <option value="fun">Fun</option>
                </select>
            </div>
            <div>
                <label for="date">Date</label>
                <input type="date" id="date">
            </div>
            <div class="full-width">
                <label for="note">Note (Optional)</label>
                <input type="text" id="note" placeholder="What was this for?">
            </div>
        </div>
        <button type="submit" id="add-expense">Add Expense</button>
        <div id="form-error"></div>
    </form>

    <!-- Filters -->
    <div class="filters">
        <label>Filters</label>
        <div class="form-group">
            <select id="filter-category">
                <option value="all">All Categories</option>
                <option value="groceries">Groceries</option>
                <option value="transport">Transport</option>
                <option value="bills">Bills</option>
                <option value="fun">Fun</option>
            </select>
            <input type="date" id="filter-from" placeholder="From">
            <input type="date" id="filter-to" placeholder="To">
        </div>
    </div>

    <!-- Summary -->
    <div id="total-display">Total: <span id="total">0.00</span></div>
    <div class="summary-grid" id="category-summaries">
        <!-- Generated via JS -->
    </div>

    <!-- List -->
    <ul id="expense-list" class="expense-list"></ul>
</div>

<script>
    // --- State Management ---
    let expenses = JSON.parse(localStorage.getItem('expenses')) || [];

    const form = document.getElementById('expense-form');
    const amountInput = document.getElementById('amount');
    const categoryInput = document.getElementById('category');
    const dateInput = document.getElementById('date');
    const noteInput = document.getElementById('note');
    const addBtn = document.getElementById('add-expense');
    const formError = document.getElementById('form-error');

    const filterCat = document.getElementById('filter-category');
    const filterFrom = document.getElementById('filter-from');
    const filterTo = document.getElementById('filter-to');

    const listContainer = document.getElementById('expense-list');
    const totalDisplay = document.getElementById('total');
    const summaryContainer = document.getElementById('category-summaries');

    // --- Core Functions ---

    function save() {
        localStorage.setItem('expenses', JSON.stringify(expenses));
        render();
    }

    function render() {
        const catFilter = filterCat.value;
        const fromDate = filterFrom.value ? new Date(filterFrom.value) : null;
        const toDate = filterTo.value ? new Date(filterTo.value) : null;

        // Normalize dates for comparison (strip time components)
        if (fromDate) fromDate.setHours(0, 0, 0, 0);
        if (toDate) toDate.setHours(23, 59, 59, 999);

        // Filter Logic
        const visibleExpenses = expenses
            .filter(exp => {
                const expDate = new Date(exp.date);
                const matchesCat = catFilter === 'all' || exp.category === catFilter;
                const matchesFrom = !fromDate || expDate >= fromDate;
                const matchesTo = !toDate || expDate <= toDate;
                return matchesCat && matchesFrom && matchesTo;
            })
            // Sort newest first (by date string since YYYY-MM-DD is lexicographically sortable)
            .sort((a, b) => b.date.localeCompare(a.date));

        // Clear UI
        listContainer.innerHTML = '';
        summaryContainer.innerHTML = '';
        let runningTotal = 0;
        const catTotals = { groceries: 0, transport: 0, bills: 0, fun: 0 };

        // Populate Rows and Totals
        visibleExpenses.forEach(exp => {
            runningTotal += parseFloat(exp.amount);
            catTotals[exp.category] += parseFloat(exp.amount);

            const li = document.createElement('li');
            li.className = 'expense';
            li.innerHTML = `
                <div class="exp-info">
                    <span class="exp-meta">${exp.category.toUpperCase()}: $${parseFloat(exp.amount).toFixed(2)}</span>
                    <span class="exp-date">${exp.date} ${exp.note ? '— ' + exp.note : ''}</span>
                </div>
                <button class="exp-del" onclick="deleteExpense(${exp.id})">Delete</button>
            `;
            listContainer.appendChild(li);
        });

        // Update Total Display
        totalDisplay.textContent = runningTotal.toFixed(2);

        // Update Category Summary Elements
        Object.keys(catTotals).forEach(cat => {
            const div = document.createElement('div');
            div.className = 'cat-total';
            div.setAttribute('data-cat', cat);
            div.textContent = `${cat}: $${catTotals[cat].toFixed(2)}`;
            summaryContainer.appendChild(div);
        });
    }

    function deleteExpense(id) {
        expenses = expenses.filter(e => e.id !== id);
        save();
    }

    // --- Event Listeners ---

    form.addEventListener('submit', (e) => {
        e.preventDefault();
        formError.textContent = '';

        const amount = parseFloat(amountInput.value);
        const date = dateInput.value;
        const category = categoryInput.value;
        const note = noteInput.value;

        // Validation
        if (isNaN(amount) || amount <= 0) {
            formError.textContent = 'Please enter a valid positive numeric amount.';
            return;
        }
        if (!date) {
            formError.textContent = 'Please select a date.';
            return;
        }

        const newExpense = {
            id: Date.now(), // unique ID
            amount,
            category,
            date,
            note
        };

        expenses.push(newExpense);
        save();

        // Reset form
        amountInput.value = '';
        noteInput.value = '';
    });

    [filterCat, filterFrom, filterTo].forEach(el => {
        el.addEventListener('change', render);
    });

    // Initial Load
    render();

</script>

</body>
</html>
